  CONSTRAINT "claim_submitted_at_pattern" CHECK (("submitted_at" ~ 'Z$')),
  CONSTRAINT "claim_overdue_reported_at_format" CHECK (((('date-time' = 'date') AND ("overdue_reported_at" ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$')) OR (('date-time' = 'date-time') AND ("overdue_reported_at" ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})$')))),
