CREATE FUNCTION "claims"."claim__lines_count"(k0 TEXT) RETURNS void LANGUAGE plpgsql AS $$
DECLARE n integer; listed boolean;
BEGIN
  SELECT TRUE INTO listed FROM "claims"."claim" WHERE "claim_id" = k0;
  IF NOT FOUND THEN RETURN; END IF;
  SELECT count(*) INTO n FROM "claims"."claim__lines" WHERE "claim_id" = k0;
  IF listed AND n < 1 THEN RAISE EXCEPTION '%', 'Must have at least 1 items' USING ERRCODE = 'check_violation', CONSTRAINT = 'claim__lines_minItems', TABLE = 'claim__lines'; END IF;
  IF n > 50 THEN RAISE EXCEPTION '%', 'Must have at most 50 items' USING ERRCODE = 'check_violation', CONSTRAINT = 'claim__lines_maxItems', TABLE = 'claim__lines'; END IF;
END $$;
